def set_cell(cell, fill=None, border=None):
    tcPr = cell._tc.get_or_add_tcPr()
    if fill:
        shd = OxmlElement('w:shd'); shd.set(qn('w:fill'), fill); tcPr.append(shd)
    cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER

def font(run, size=11, bold=False, color=None, italic=False):
    run.font.name = 'Calibri'; run._element.rPr.rFonts.set(qn('w:ascii'), 'Calibri'); run._element.rPr.rFonts.set(qn('w:hAnsi'), 'Calibri')
    run.font.size = Pt(size); run.bold = bold; run.italic = italic
    if color: run.font.color.rgb = RGBColor.from_string(color)

def style_doc(doc):
    sec = doc.sections[0]
    sec.top_margin = Inches(0.85); sec.bottom_margin = Inches(0.8); sec.left_margin = Inches(0.9); sec.right_margin = Inches(0.9)
    sec.header_distance = Inches(.35); sec.footer_distance = Inches(.35)
    normal = doc.styles['Normal']; normal.font.name='Calibri'; normal._element.rPr.rFonts.set(qn('w:ascii'), 'Calibri'); normal._element.rPr.rFonts.set(qn('w:hAnsi'), 'Calibri'); normal.font.size=Pt(10.5)
    normal.paragraph_format.space_after=Pt(6); normal.paragraph_format.line_spacing=1.22
    for name,size,col,bef,aft in [('Heading 1',16,BLUE,16,8),('Heading 2',13,BLUE,12,6),('Heading 3',11,NAVY,8,4)]:
        s=doc.styles[name]; s.font.name='Calibri'; s._element.rPr.rFonts.set(qn('w:ascii'),'Calibri'); s._element.rPr.rFonts.set(qn('w:hAnsi'),'Calibri'); s.font.size=Pt(size); s.font.color.rgb=RGBColor.from_string(col); s.font.bold=True
        s.paragraph_format.space_before=Pt(bef); s.paragraph_format.space_after=Pt(aft); s.paragraph_format.keep_with_next=True
    header=sec.header.paragraphs[0]; header.alignment=WD_ALIGN_PARAGRAPH.RIGHT
    r=header.add_run('VentureMind AI | BSc Software Engineering Dissertation'); font(r,8,False,'6B7280')
    footer=sec.footer.paragraphs[0]; footer.alignment=WD_ALIGN_PARAGRAPH.CENTER
    r=footer.add_run('Vaishnavadevy Vasanthakumar | st20312021 | CSE6035 WRIT1'); font(r,8,False,'6B7280')

def p(doc, text='', style=None, align=None, size=None, bold=False, color=None, italic=False):
    para=doc.add_paragraph(style=style)
    if align is not None: para.alignment=align
    r=para.add_run(text); font(r,size or (16 if style=='Heading 1' else 11),bold,color,italic)
    return para

def heading(doc, text, level=1): return p(doc,text,style=f'Heading {level}')
def bullet(doc,text):
    para=doc.add_paragraph(style='List Bullet'); para.paragraph_format.space_after=Pt(3); r=para.add_run(text); font(r,10.5); return para
def numbered(doc,text):
    para=doc.add_paragraph(style='List Number'); para.paragraph_format.space_after=Pt(3); r=para.add_run(text); font(r,10.5); return para

