    for x in figs: p(doc,x,size=10.5)
    heading(doc,'List of Tables',1)
    tables=['Table 1. Project objectives and success measures','Table 2. Comparative review of related approaches','Table 3. Functional requirements','Table 4. Non-functional requirements','Table 5. Risk-engine scoring dimensions','Table 6. Representative API endpoints','Table 7. Test cases and outcomes']
