def add_screenshot(doc, path, caption):
    image = Path(path)
    if image.exists():
        para = doc.add_paragraph(); para.alignment = WD_ALIGN_PARAGRAPH.CENTER
        para.add_run().add_picture(str(image), width=Inches(6.2))
        p(doc, caption, align=WD_ALIGN_PARAGRAPH.CENTER, size=9, italic=True, color='4B5563')
    else:
        p(doc, f'[Screenshot unavailable at generation time: {image.name}]', italic=True, color='B91C1C')

