def count_words(doc):
    words=[]
    for para in doc.paragraphs:
        words += para.text.split()
    for t in doc.tables:
        for row in t.rows:
            for cell in row.cells:
                for para in cell.paragraphs: words += para.text.split()
    return len(words)

def main():
    OUT.parent.mkdir(parents=True, exist_ok=True)
    d=Document(); style_doc(d)
    title_page(d); declaration(d); abstract(d); toc(d); intro(d); literature(d); literature_extension(d); planning(d); requirements(d); design(d); implementation(d); testing(d); evaluation_discussion(d); conclusion(d); refs(d); appendix(d)
    # Recorded after body drafting; table/figure text is included, references and appendices are excluded in the stated thesis count.
    d.core_properties.title='VentureMind AI Final Dissertation'
    d.core_properties.author='Vaishnavadevy Vasanthakumar'
    d.save(OUT)
    print(f'Created {OUT}')
    print(f'Document word count (all content including references/appendices): {count_words(d)}')

if __name__=='__main__': main()
